type FiscalisationPortType interface {
	Invoice(request *InvoiceRequest) (*InvoiceResponse, error)

	InvoiceContext(ctx context.Context, request *InvoiceRequest) (*InvoiceResponse, error)

	BusinessPremise(request *BusinessPremiseRequest) (*BusinessPremiseResponse, error)

	BusinessPremiseContext(ctx context.Context, request *BusinessPremiseRequest) (*BusinessPremiseResponse, error)

	Echo(request *string) (*string, error)

	EchoContext(ctx context.Context, request *string) (*string, error)
}

type fiscalisationPortType struct {
	client *soap.Client
}

func NewFiscalisationPortType(client *soap.Client) FiscalisationPortType {
	return &fiscalisationPortType{
		client: client,
	}
}

func (service *fiscalisationPortType) InvoiceContext(ctx context.Context, request *InvoiceRequest) (*InvoiceResponse, error) {
	response := new(InvoiceResponse)
	err := service.client.CallContext(ctx, "/invoices", request, response)
	if err != nil {
		return nil, err
	}

	return response, nil
}

func (service *fiscalisationPortType) Invoice(request *InvoiceRequest) (*InvoiceResponse, error) {
	return service.InvoiceContext(
		context.Background(),
		request,
	)
}

func (service *fiscalisationPortType) BusinessPremiseContext(ctx context.Context, request *BusinessPremiseRequest) (*BusinessPremiseResponse, error) {
	response := new(BusinessPremiseResponse)
	err := service.client.CallContext(ctx, "/invoices/register", request, response)
	if err != nil {
		return nil, err
	}

	return response, nil
}

func (service *fiscalisationPortType) BusinessPremise(request *BusinessPremiseRequest) (*BusinessPremiseResponse, error) {
	return service.BusinessPremiseContext(
		context.Background(),
		request,
	)
}

func (service *fiscalisationPortType) EchoContext(ctx context.Context, request *string) (*string, error) {
	response := new(string)
	err := service.client.CallContext(ctx, "/echo", request, response)
	if err != nil {
		return nil, err
	}

	return response, nil
}

func (service *fiscalisationPortType) Echo(request *string) (*string, error) {
	return service.EchoContext(
		context.Background(),
		request,
	)
}
